    {value: 'inactive', label: 'Inactive'},
  ]},
] as const;

interface User extends Record<string, unknown> {
  id: string;
  name: string;
  status: 'active' | 'inactive';
}

const columns: TableColumn<User>[] = [
  {key: 'name', header: 'Name', filter: 'name'},
  {key: 'status', header: 'Status', filter: 'status'},
