function UsersTable({users}: {users: User[]}) {
  const {config, applyFilters} = usePowerSearchConfig(fields);
  const {filters, onFilterChange, clearAll} = useTableFilterState();
  const filterPlugin = useTableFiltering<User>({filters, onFilterChange, searchConfig: config});
  // The plugin draws the controls. You remove the rows that do not match.
  const visibleUsers = applyFilters(toSearchFilters(filters, columns, config), users);

  return (
    <Table
      data={visibleUsers}
      columns={columns}
      idKey="id"
      plugins={{filter: filterPlugin}}
      emptyState={
        <EmptyState
          title="No matching users"
          description="Change or clear the filters."
          actions={<Button label="Clear filters" onClick={clearAll} />}
        />
      }
    />
  );
}

interface Walk extends Record<string, unknown> { id: string; name: string; km: number }
const columns: TableColumn<Walk>[] = [{key: 'name', header: 'Name'}, {key: 'km', header: 'Km'}];

const pageSize = 20;
const [page, setPage] = useState(1);
// Pass the row type: TypeScript cannot infer it from the config.
const paginationPlugin = useTablePagination<Walk>({
  page,
  onPageChange: setPage,
  totalItems: walks.length,
  pageSize,
});
// The plugin draws the page controls; pass only the current page's rows.
const pageRows = walks.slice((page - 1) * pageSize, page * pageSize);

<Table data={pageRows} columns={columns} idKey="id" plugins={{pagination: paginationPlugin}} />;

const [expandedKeys, setExpandedKeys] = useState(new Set());
const expansion = useTableRowExpansion({
  expandedKeys,
  onToggle: key =>
    setExpandedKeys(prev => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    }),
  getRowKey: item => item.id,
  getRowLabel: item => item.name,
  renderExpanded: item => <OrderDetails order={item} />,
});

<Table data={orders} columns={columns} idKey="id" plugins={{expansion}} />;

// useTableRowExpansion is now for DETAIL PANELS, not tree rows. If you used
// it to render nested child rows that reuse the parent columns, move to
// useTableTreeData + useTableTreeState.

// BEFORE (tree rows via useTableRowExpansion + useTableRowExpansionState):
const {data, expansionConfig} = useTableRowExpansionState({
  baseData: tree,
  getChildren: item => item.children ?? [],
  getRowKey: item => item.id,
  expandedKeys,
  setExpandedKeys,
});
const expansion = useTableRowExpansion(expansionConfig);
<Table data={data} columns={columns} idKey="id" plugins={{expansion}} />;

// AFTER (tree rows via the tree plugin):
const {visibleData, treeConfig} = useTableTreeState({
  data: tree,                   // nested data
  idKey: 'id',                  // or a function: idKey={item => item.id}
  childrenKey: 'children',      // replaces getChildren
  defaultExpandedIds: ['root'], // or controlled: expandedIds + onExpandedIdsChange
});
const tree = useTableTreeData({
  ...treeConfig,
  hasExpandAllControl: true,    // was isAllExpanded + onToggleExpandAll
  hasRowClickExpansion: true,   // same prop name
});
<Table data={visibleData} columns={columns} idKey="id" plugins={{tree}} />;

// useTableSelectionState excludes both kinds of row from select-all.
const {selectionConfig} = useTableSelectionState({
  data: visibleUsers,
  idKey: 'id',
  selectedKeys,
  setSelectedKeys,
  // System accounts can never be selected: no checkbox.
  getIsItemSelectable: user => !user.isSystem,
  // Locked accounts show a disabled checkbox that keeps its state.
  getIsItemEnabled: user => !user.isLocked,
});
const selectionPlugin = useTableSelection(selectionConfig);

<Table
  data={visibleUsers}
